// I Love TV! Suite — input-bar workspace
export function setup(ctx) {
  const s={chatId:null,tab:'broadcast',ledger:{affinity:0,dynamic:'',continuity:{},settings:{expandChoices:true,trackerInterval:1},lastActions:[]},suite:{enabled:true,selectedVersion:'3.5',rpgMode:false,versions:[],blocks:[]},connections:[],choices:[],block:null,search:'',choiceBusy:false,rewriteBusy:false,requestId:null};
  let modal=null; const cleanups=[];
  const esc=(v='')=>String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;');
  const send=(type,p={})=>ctx.sendToBackend({type,chatId:s.chatId||undefined,...p});
  const requestState=()=>send('control_room:get_state');
  function toast(message){let e=document.getElementById('ilovetv-suite-toast');if(!e){e=document.createElement('div');e.id='ilovetv-suite-toast';e.style.cssText='position:fixed;bottom:84px;left:50%;transform:translateX(-50%);z-index:99999;padding:8px 16px;border:1px solid #a78bfa;border-radius:999px;background:#17131f;color:#fff;font:700 12px system-ui;box-shadow:0 8px 28px #000a;pointer-events:none;transition:opacity .2s';document.body.appendChild(e)}e.textContent=message;e.style.opacity='1';setTimeout(()=>e.style.opacity='0',2800)}
  function composer(){return document.querySelector('textarea[name="chat-message"]')||document.querySelector('[data-component="InputArea"] textarea')||document.querySelector('textarea[placeholder*="message" i]')}
  function writeComposer(text){const t=composer();if(!t){toast('Could not locate Lumiverse’s message composer.');return false}const set=Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype,'value')?.set;t.focus();if(set)set.call(t,text);else t.value=text;t.dispatchEvent(new InputEvent('input',{bubbles:true,composed:true,inputType:'insertText',data:text}));t.dispatchEvent(new Event('change',{bubbles:true,composed:true}));t.selectionStart=t.selectionEnd=t.value.length;toast('Editable draft placed in the composer.');return true}
  function parseChoices(content){const text=String(content||'');const body=text.match(/<cyoa_choices\b[^>]*>([\s\S]*?)<\/cyoa_choices>/i)?.[1]||text;return body.split(/\r?\n/).map(x=>x.match(/^\s*\[(\d+)\]\s*(.+?)\s*$/)).filter(Boolean).map(m=>({number:Number(m[1]),text:m[2].trim()})).slice(0,8)}
  function captureChoices(content){const c=parseChoices(content);if(!c.length)return false;s.choices=c;toast(`${c.length} Director’s Cut choices are ready in the TV Suite.`);render();return true}
  function choose(index){const c=s.choices[index];if(!c||s.choiceBusy)return;if(s.ledger.settings?.expandChoices===false){if(writeComposer(String(c.number)))s.choices=[];render();return}s.choiceBusy=true;s.requestId=crypto.randomUUID();toast('Writing the selected option as {{user}}…');send('control_room:expand_choice',{requestId:s.requestId,option:`[${c.number}] ${c.text}`});render()}
  const tabs=[['broadcast','📺 Broadcast'],['preset','🎛️ Preset'],['blocks','🧱 Blocks'],['director','🎬 Director'],['memory','🧠 Memory'],['tools','🧰 Tools']];
  const css=`<style>.tv{color:var(--lumiverse-text,#eee);font:13px/1.45 system-ui}.tv-head{display:flex;align-items:center;gap:12px;padding:2px 2px 13px;border-bottom:1px solid #ffffff14}.tv-logo{width:42px;height:42px;display:grid;place-items:center;border:1px solid #a78bfa66;border-radius:12px;background:linear-gradient(145deg,#392c4e,#17131f);font-size:24px;box-shadow:0 0 22px #8b5cf633}.tv-title{font-size:17px;font-weight:900}.tv-live{margin-left:auto;font-size:10px;font-weight:800;color:#fca5a5}.tv-dot{display:inline-block;width:8px;height:8px;margin-right:6px;border-radius:50%;background:#ef4444;box-shadow:0 0 9px #ef4444}.tv-tabs{display:flex;gap:5px;overflow:auto;padding:11px 0}.tv-tab{white-space:nowrap;border:1px solid #ffffff16;border-radius:999px;background:#ffffff08;color:inherit;padding:6px 10px;cursor:pointer}.tv-tab.on{border-color:#a78bfa;background:#8b5cf626;color:#c4b5fd}.tv-panel{display:flex;flex-direction:column;gap:10px;max-height:620px;overflow:auto;padding:2px}.tv-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.tv-card,.tv-row{border:1px solid #ffffff14;border-radius:10px;background:#ffffff07;padding:10px}.tv-row{display:flex;flex-direction:column;gap:5px}.tv-label{font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase;color:#b99cff}.tv-muted{font-size:11px;color:var(--lumiverse-text-dim,#999)}.tv-input{box-sizing:border-box;width:100%;padding:8px;border:1px solid #ffffff1f;border-radius:7px;background:#0f0d14;color:inherit}.tv-btn{border:1px solid #8b5cf680;border-radius:7px;background:#8b5cf626;color:#ddd6fe;padding:7px 11px;font-weight:800;cursor:pointer}.tv-btn.danger{border-color:#ef444466;color:#fecaca;background:#ef444414}.tv-actions{display:flex;gap:7px;flex-wrap:wrap}.tv-list{margin:5px 0 0;padding-left:18px}.tv-blocks{display:grid;grid-template-columns:minmax(220px,.8fr) minmax(300px,1.4fr);gap:10px}.tv-block-list{max-height:500px;overflow:auto}.tv-block{display:flex;width:100%;gap:8px;align-items:center;text-align:left;border:0;border-bottom:1px solid #ffffff0d;background:transparent;color:inherit;padding:8px;cursor:pointer}.tv-block.on{background:#8b5cf61c}.tv-block-name{flex:1}.tv-chip{font-size:9px;border:1px solid #ffffff1a;border-radius:999px;padding:2px 5px}.tv-editor{min-height:310px;font:11px/1.45 ui-monospace,monospace;resize:vertical}.tv-choice{width:100%;text-align:left;border:1px solid #ffffff16;border-left:3px solid #a78bfa;border-radius:8px;background:#ffffff08;color:inherit;padding:10px;cursor:pointer}.tv-meter{font:900 28px ui-monospace;color:#c4b5fd}.tv-log{font:10px/1.45 ui-monospace;padding:4px 0;border-bottom:1px dashed #ffffff12}@media(max-width:680px){.tv-grid,.tv-blocks{grid-template-columns:1fr}}</style>`;
  const list=(a,f)=>Array.isArray(a)&&a.length?`<ul class="tv-list">${a.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:`<div class="tv-muted">${f}</div>`;
  function broadcast(){const t=s.ledger.lastTurn||{};return `<div class="tv-grid"><div class="tv-card"><div class="tv-label">Affinity</div><div class="tv-meter">${Number(s.ledger.affinity)||0}%</div><div class="tv-muted">Last delta ${Number(t.delta||0)>=0?'+':''}${Number(t.delta||0)}%</div></div><div class="tv-card"><div class="tv-label">Locked checks</div><div style="font:800 18px ui-monospace">D4 ${t.pathRoll||'—'} · D20 ${t.d20Roll||'—'}</div><div class="tv-muted">${t.backgroundSucceeded?'Director pass successful':'Awaiting a successful pass'}</div></div></div><div class="tv-card"><div class="tv-label">Dynamic subtext</div>${esc(s.ledger.dynamic||'Awaiting analysis…')}</div><div class="tv-card"><div class="tv-label">Immediate episode target</div>${esc(s.ledger.continuity?.episodeTarget||'Awaiting analysis…')}</div><div class="tv-card"><div class="tv-label">Season arc</div>${esc(s.ledger.continuity?.seasonArc||'Awaiting analysis…')}</div>`}
  function preset(){const opts=(s.suite.versions||[]).map(v=>`<option value="${esc(v.id)}" ${v.id===s.suite.selectedVersion?'selected':''}>${esc(v.label)} · ${v.blockCount} blocks</option>`).join('');return `<div class="tv-row"><label class="tv-label">Bundled preset version</label><select id="tv-version" class="tv-input">${opts}</select><div class="tv-muted">Assembled by the extension; the external preset is no longer required.</div></div><label class="tv-card"><input id="tv-enabled" type="checkbox" ${s.suite.enabled!==false?'checked':''}> Use the bundled suite prompt for generations</label><div class="tv-card"><div class="tv-label">Version library</div>${(s.suite.versions||[]).map(v=>`<p><b>${esc(v.label)}</b><br><span class="tv-muted">${esc(v.description||'')}</span></p>`).join('')}</div>`}
  function blocks(){const q=s.search.toLowerCase();const bs=(s.suite.blocks||[]).filter(b=>!q||b.name.toLowerCase().includes(q));const items=bs.map(b=>`<button class="tv-block ${s.block?.id===b.id?'on':''}" data-block="${esc(b.id)}"><input type="checkbox" tabindex="-1" ${b.enabled?'checked':''}><span class="tv-block-name">${esc(b.name)}</span>${b.edited?'<span class="tv-chip">edited</span>':''}</button>`).join('');const ed=s.block?`<div class="tv-row"><div class="tv-label">${esc(s.block.name)}</div><textarea id="tv-content" class="tv-input tv-editor">${esc(s.block.content||'')}</textarea><textarea id="tv-directions" class="tv-input" rows="3" placeholder="Tell the selected model how to rewrite this prompt…"></textarea><div class="tv-actions"><button id="tv-save-block" class="tv-btn">Save block</button><button id="tv-rewrite" class="tv-btn">${s.rewriteBusy?'Writing…':'AI rewrite draft'}</button><button id="tv-reset" class="tv-btn danger">Reset to bundled</button></div><div class="tv-muted">AI rewrites remain drafts until you save.</div></div>`:'<div class="tv-card tv-muted">Select a block to inspect or edit it.</div>';return `<div class="tv-blocks"><div><input id="tv-search" class="tv-input" placeholder="Search 84 blocks…" value="${esc(s.search)}"><div class="tv-card tv-block-list">${items}</div></div>${ed}</div>`}
  function director(){const opts=['<option value="">Active/default connection</option>',...(s.connections||[]).map(c=>`<option value="${esc(c.id)}" ${c.id===s.ledger.selectedConnection?'selected':''}>${esc(c.name)}</option>`)].join('');const logs=(s.ledger.lastActions||[]).slice(-14).reverse().map(x=>`<div class="tv-log">${esc(x)}</div>`).join('');return `<div class="tv-row"><label class="tv-label">Background connection</label><select id="tv-connection" class="tv-input">${opts}</select></div><div class="tv-row"><label class="tv-label">Author’s note</label><textarea id="tv-note" class="tv-input" rows="3">${esc(s.ledger.authorNote||'')}</textarea></div><div class="tv-row"><label class="tv-label">Tracker cadence</label><input id="tv-interval" class="tv-input" type="number" min="1" max="10" value="${Number(s.ledger.settings?.trackerInterval||1)}"></div><button id="tv-save-director" class="tv-btn">Save director settings</button><div class="tv-card"><div class="tv-label">Director telemetry</div>${logs||'<div class="tv-muted">No passes yet.</div>'}</div>`}
  function memory(){const c=s.ledger.continuity||{};return `<div class="tv-card"><div class="tv-label">Running story summary</div>${esc(c.runningSummary||'The suite summarizer will update this on the next tracker pass.')}</div><div class="tv-card"><div class="tv-label">Core memories</div>${list(c.coreMemories,'None captured yet.')}</div><div class="tv-card"><div class="tv-label">B-plots & flags</div>${list(c.bPlots,'None captured yet.')}</div><div class="tv-card"><div class="tv-label">Possible future branches</div>${list(c.futureBranches,'None predicted yet.')}</div>`}
  function tools(){const choices=s.choiceBusy?'<div class="tv-card">🎙️ Writing {{user}}’s draft…</div>':s.choices.length?s.choices.map((c,i)=>`<button class="tv-choice" data-choice="${i}">[${c.number}] ${esc(c.text)}</button>`).join(''):'<div class="tv-card tv-muted">CYOA choices will appear here after a response.</div>';return `<label class="tv-card"><input id="tv-expand" type="checkbox" ${s.ledger.settings?.expandChoices!==false?'checked':''}> AI writes selected CYOA choices as {{user}}</label><label class="tv-card"><input id="tv-rpg" type="checkbox" ${s.suite.rpgMode?'checked':''}> RPG mode: locked checks, inventory, conditions, and objectives</label>${choices}`}
  function render(){if(!modal)return;const panel=s.tab==='broadcast'?broadcast():s.tab==='preset'?preset():s.tab==='blocks'?blocks():s.tab==='director'?director():s.tab==='memory'?memory():tools();modal.root.innerHTML=`${css}<div class="tv"><div class="tv-head"><div class="tv-logo">📺</div><div><div class="tv-title">I LOVE TV! SUITE</div><div class="tv-muted">Preset · Director · Memory · Interactive tools</div></div><div class="tv-live"><span class="tv-dot"></span>${s.suite.enabled===false?'STANDBY':'ON AIR'}</div></div><nav class="tv-tabs">${tabs.map(([id,l])=>`<button class="tv-tab ${id===s.tab?'on':''}" data-tab="${id}">${l}</button>`).join('')}</nav><section class="tv-panel">${panel}</section></div>`;bind()}
  function bind(){modal.root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{s.tab=b.dataset.tab;render()});modal.root.querySelector('#tv-version')?.addEventListener('change',e=>send('suite:select_version',{versionId:e.target.value}));modal.root.querySelector('#tv-enabled')?.addEventListener('change',e=>send('suite:save_settings',{enabled:e.target.checked,rpgMode:s.suite.rpgMode}));modal.root.querySelector('#tv-rpg')?.addEventListener('change',e=>send('suite:save_settings',{enabled:s.suite.enabled,rpgMode:e.target.checked}));modal.root.querySelector('#tv-expand')?.addEventListener('change',e=>send('control_room:save_ledger',{ledger:{settings:{...s.ledger.settings,expandChoices:e.target.checked}}}));modal.root.querySelector('#tv-search')?.addEventListener('input',e=>{s.search=e.target.value;render()});modal.root.querySelectorAll('[data-block]').forEach(b=>b.onclick=e=>{if(e.target instanceof HTMLInputElement)send('suite:save_block',{blockId:b.dataset.block,enabled:e.target.checked});else send('suite:get_block',{blockId:b.dataset.block})});modal.root.querySelector('#tv-save-block')?.addEventListener('click',()=>send('suite:save_block',{blockId:s.block.id,content:modal.root.querySelector('#tv-content').value}));modal.root.querySelector('#tv-reset')?.addEventListener('click',()=>send('suite:reset_block',{blockId:s.block.id}));modal.root.querySelector('#tv-rewrite')?.addEventListener('click',()=>{s.rewriteBusy=true;s.requestId=crypto.randomUUID();send('suite:rewrite_block',{requestId:s.requestId,blockId:s.block.id,content:modal.root.querySelector('#tv-content').value,directions:modal.root.querySelector('#tv-directions').value});render()});modal.root.querySelector('#tv-save-director')?.addEventListener('click',()=>send('control_room:save_ledger',{ledger:{selectedConnection:modal.root.querySelector('#tv-connection').value,authorNote:modal.root.querySelector('#tv-note').value.trim(),settings:{...s.ledger.settings,trackerInterval:Math.max(1,Math.min(10,Number(modal.root.querySelector('#tv-interval').value||1)))}}}));modal.root.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.choice)))}
  function open(){requestState();if(!modal){modal=ctx.ui.showModal({title:'📺 I Love TV! Suite',width:820,maxHeight:820});modal.onDismiss(()=>modal=null)}render()}
  cleanups.push(ctx.onBackendMessage(p=>{if(!p)return;if(p.type==='control_room:state_data'||p.type==='control_room:save_success'){if(p.chatId)s.chatId=p.chatId;if(p.ledger)s.ledger=p.ledger;if(p.connections)s.connections=p.connections;if(p.suite)s.suite={...s.suite,...p.suite};render()}if(p.type==='suite:config_saved'){s.suite={...s.suite,...p.suite};toast('Suite configuration saved.');render()}if(p.type==='suite:block_data'){s.block=p.block;s.tab='blocks';render()}if(p.type==='suite:block_saved'){s.block=p.block;s.suite.blocks=p.blocks||s.suite.blocks;toast('Prompt block saved.');render()}if(p.type==='suite:rewrite_ready'&&p.requestId===s.requestId){s.rewriteBusy=false;s.block={...s.block,content:p.content};toast('AI rewrite ready for review.');render()}if(p.type==='suite:rewrite_error'&&p.requestId===s.requestId){s.rewriteBusy=false;toast(`Prompt rewrite failed: ${p.error}`);render()}if(p.type==='control_room:choice_expanded'&&p.requestId===s.requestId){s.choiceBusy=false;s.requestId=null;if(writeComposer(p.text))s.choices=[];render()}if(p.type==='control_room:choice_error'&&p.requestId===s.requestId){s.choiceBusy=false;s.requestId=null;toast(`Choice writer failed: ${p.error}`);render()}}));
  if(ctx.messages?.registerTagInterceptor)cleanups.push(ctx.messages.registerTagInterceptor({tagName:'cyoa_choices'},p=>{if(!p.isStreaming)captureChoices(p.content)}));if(ctx.events?.on){cleanups.push(ctx.events.on('GENERATION_ENDED',p=>captureChoices(p?.content)));cleanups.push(ctx.events.on('CHAT_SWITCHED',p=>{s.chatId=p?.chatId||null;s.choices=[];s.block=null;requestState();render()}))}if(ctx.ui?.registerInputBarAction){const a=ctx.ui.registerInputBarAction({id:'i-love-tv-suite',label:'I Love TV! Suite',iconSvg:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="7" width="20" height="15" rx="2"/><path d="m17 2-5 5-5-5"/><circle cx="17" cy="14" r="2"/><path d="M6 13h6M6 17h5"/></svg>'});cleanups.push(a.onClick(open),()=>a.destroy())}requestState();return()=>{cleanups.reverse().forEach(f=>{try{f?.()}catch{}});modal?.dismiss?.();document.getElementById('ilovetv-suite-toast')?.remove()}
}

